@admin_bp.route("/purge-user", methods=["POST"])
@require_role("admin")
def purge_user_data():
    """Purge a departed user's orders (data-erasure request)."""
    payload = request.get_json(silent=True) or {}
    username = payload.get("username", "")
    engine = get_engine()
    with engine.connect() as conn:
        conn.exec_driver_sql(
            "DELETE FROM orders WHERE user_id = "
            "(SELECT id FROM users WHERE username = '%s')" % username
        )
        conn.commit()
    return jsonify({"status": "purged"})

def require_role(minimum_role: str):
    """Require at least the given role (user < manager < admin)."""

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            user = get_current_user()
            if user is None:
                return jsonify({"error": "authentication required"}), 401
            if ROLE_RANK.get(user.role, 0) < ROLE_RANK.get(minimum_role, 99):
                return jsonify({"error": "insufficient role"}), 403
            g.current_user = user
            return fn(*args, **kwargs)

        return wrapper

    return decorator
